{
  "id": "malaria-vector-borne-transmission-model-epi",
  "name": "Malaria Vector-Borne Transmission Model",
  "description": "Illustrative Malaria Vector-Borne Transmission Model.\n\nSource reconciliation 2026-10-20: Corrected the unrelated chondrogenesis DOI to the publisher book record. This correction establishes bibliographic identity only. This generated definition is illustrative; no specific book chapter/equation, parameter table, initial values, unit system or calibration has been traced to it. The Ross-Macdonald-style structure includes bednet, spraying and seasonal extensions without an identified book equation or calibration; no empirical provenance supports the displayed intervention efficacy and transmission values. Equations, initial values, flow topology and layout are unchanged. Scientific/source fidelity remains unverified.",
  "stocks": [
    {
      "id": "stock-susceptible-humans",
      "name": "Susceptible Humans",
      "initial_value": 9900,
      "equation": "",
      "position": {
        "x": 150,
        "y": 200
      }
    },
    {
      "id": "stock-infected-humans",
      "name": "Infected Humans",
      "initial_value": 100,
      "equation": "",
      "position": {
        "x": 350,
        "y": 200
      }
    },
    {
      "id": "stock-susceptible-mosquitoes",
      "name": "Susceptible Mosquitoes",
      "initial_value": 50000,
      "equation": "",
      "position": {
        "x": 550,
        "y": 200
      }
    },
    {
      "id": "stock-exposed-mosquitoes",
      "name": "Exposed Mosquitoes",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 750,
        "y": 200
      }
    },
    {
      "id": "stock-infectious-mosquitoes",
      "name": "Infectious Mosquitoes",
      "initial_value": 500,
      "equation": "",
      "position": {
        "x": 150,
        "y": 350
      }
    }
  ],
  "flows": [
    {
      "id": "flow-human-infection",
      "name": "Human Infection",
      "equation": "Biting_Rate * Infectious_Mosquitoes * Susceptible_Humans / Human_Population * Transmission_Mosquito_to_Human * (1 - Bednet_Efficacy * Bednet_Coverage)",
      "from_stock": "stock-susceptible-humans",
      "to_stock": "stock-infected-humans",
      "position": {
        "x": 250,
        "y": 200
      }
    },
    {
      "id": "flow-human-recovery",
      "name": "Human Recovery",
      "equation": "Infected_Humans / Human_Infectious_Period",
      "from_stock": "stock-infected-humans",
      "to_stock": "stock-susceptible-humans",
      "position": {
        "x": 450,
        "y": 200
      }
    },
    {
      "id": "flow-human-death",
      "name": "Human Death",
      "equation": "Infected_Humans * Malaria_Mortality_Rate",
      "from_stock": "stock-infected-humans",
      "to_stock": null,
      "position": {
        "x": 650,
        "y": 200
      }
    },
    {
      "id": "flow-mosquito-emergence",
      "name": "Mosquito Emergence",
      "equation": "Mosquito_Birth_Rate * Total_Mosquitoes * Seasonal_Factor",
      "from_stock": null,
      "to_stock": "stock-susceptible-mosquitoes",
      "position": {
        "x": 250,
        "y": 350
      }
    },
    {
      "id": "flow-mosquito-infection",
      "name": "Mosquito Infection",
      "equation": "Biting_Rate * Susceptible_Mosquitoes * Infected_Humans / Human_Population * Transmission_Human_to_Mosquito",
      "from_stock": "stock-susceptible-mosquitoes",
      "to_stock": "stock-exposed-mosquitoes",
      "position": {
        "x": 450,
        "y": 350
      }
    },
    {
      "id": "flow-mosquito-becoming-infectious",
      "name": "Mosquito Becoming Infectious",
      "equation": "Exposed_Mosquitoes / Extrinsic_Incubation_Period",
      "from_stock": "stock-exposed-mosquitoes",
      "to_stock": "stock-infectious-mosquitoes",
      "position": {
        "x": 650,
        "y": 350
      }
    },
    {
      "id": "flow-mosquito-death-susceptible",
      "name": "Mosquito Death Susceptible",
      "equation": "Susceptible_Mosquitoes * Mosquito_Death_Rate * (1 + IRS_Efficacy * IRS_Coverage)",
      "from_stock": "stock-susceptible-mosquitoes",
      "to_stock": null,
      "position": {
        "x": 250,
        "y": 500
      }
    },
    {
      "id": "flow-mosquito-death-exposed",
      "name": "Mosquito Death Exposed",
      "equation": "Exposed_Mosquitoes * Mosquito_Death_Rate * (1 + IRS_Efficacy * IRS_Coverage)",
      "from_stock": "stock-exposed-mosquitoes",
      "to_stock": null,
      "position": {
        "x": 450,
        "y": 500
      }
    },
    {
      "id": "flow-mosquito-death-infectious",
      "name": "Mosquito Death Infectious",
      "equation": "Infectious_Mosquitoes * Mosquito_Death_Rate * (1 + IRS_Efficacy * IRS_Coverage)",
      "from_stock": "stock-infectious-mosquitoes",
      "to_stock": null,
      "position": {
        "x": 650,
        "y": 500
      }
    }
  ],
  "variables": [
    {
      "id": "var-human-population",
      "name": "Human Population",
      "equation": "Susceptible_Humans + Infected_Humans",
      "position": {
        "x": 100,
        "y": 80
      }
    },
    {
      "id": "var-total-mosquitoes",
      "name": "Total Mosquitoes",
      "equation": "Susceptible_Mosquitoes + Exposed_Mosquitoes + Infectious_Mosquitoes",
      "position": {
        "x": 250,
        "y": 80
      }
    },
    {
      "id": "var-biting-rate",
      "name": "Biting Rate",
      "equation": "0.5",
      "position": {
        "x": 400,
        "y": 80
      }
    },
    {
      "id": "var-transmission-mosquito-to-human",
      "name": "Transmission Mosquito to Human",
      "equation": "0.3",
      "position": {
        "x": 550,
        "y": 80
      }
    },
    {
      "id": "var-transmission-human-to-mosquito",
      "name": "Transmission Human to Mosquito",
      "equation": "0.5",
      "position": {
        "x": 700,
        "y": 80
      }
    },
    {
      "id": "var-human-infectious-period",
      "name": "Human Infectious Period",
      "equation": "200",
      "position": {
        "x": 100,
        "y": 160
      }
    },
    {
      "id": "var-extrinsic-incubation-period",
      "name": "Extrinsic Incubation Period",
      "equation": "10",
      "position": {
        "x": 250,
        "y": 160
      }
    },
    {
      "id": "var-mosquito-death-rate",
      "name": "Mosquito Death Rate",
      "equation": "0.1",
      "position": {
        "x": 400,
        "y": 160
      }
    },
    {
      "id": "var-mosquito-birth-rate",
      "name": "Mosquito Birth Rate",
      "equation": "0.1",
      "position": {
        "x": 550,
        "y": 160
      }
    },
    {
      "id": "var-malaria-mortality-rate",
      "name": "Malaria Mortality Rate",
      "equation": "0.0001",
      "position": {
        "x": 700,
        "y": 160
      }
    },
    {
      "id": "var-bednet-coverage",
      "name": "Bednet Coverage",
      "equation": "0.3",
      "position": {
        "x": 100,
        "y": 240
      }
    },
    {
      "id": "var-bednet-efficacy",
      "name": "Bednet Efficacy",
      "equation": "0.5",
      "position": {
        "x": 250,
        "y": 240
      }
    },
    {
      "id": "var-irs-coverage",
      "name": "IRS Coverage",
      "equation": "0.2",
      "position": {
        "x": 400,
        "y": 240
      }
    },
    {
      "id": "var-irs-efficacy",
      "name": "IRS Efficacy",
      "equation": "0.7",
      "position": {
        "x": 550,
        "y": 240
      }
    },
    {
      "id": "var-seasonal-factor",
      "name": "Seasonal Factor",
      "equation": "1 + 0.5 * SIN(2 * PI * Time / 365)",
      "position": {
        "x": 700,
        "y": 240
      }
    },
    {
      "id": "var-vectorial-capacity",
      "name": "Vectorial Capacity",
      "equation": "(Total_Mosquitoes / Human_Population) * Biting_Rate^2 * Transmission_Mosquito_to_Human * EXP(-Mosquito_Death_Rate * Extrinsic_Incubation_Period) / Mosquito_Death_Rate",
      "position": {
        "x": 100,
        "y": 320
      }
    },
    {
      "id": "var-basic-reproduction-number",
      "name": "Basic Reproduction Number",
      "equation": "Vectorial_Capacity * Transmission_Human_to_Mosquito * Human_Infectious_Period",
      "position": {
        "x": 250,
        "y": 320
      }
    }
  ],
  "connectors": [],
  "time_settings": {
    "start": 0,
    "end": 365,
    "dt": 0.5
  },
  "created_at": "2026-01-11T20:04:50.799961Z",
  "updated_at": "2026-01-11T20:04:50.799961Z",
  "source": "https://doi.org/10.2307/j.ctvcm4gk0",
  "reference": "Keeling MJ, Rohani P. Modeling Infectious Diseases in Humans and Animals. Princeton University Press, 2008. DOI: 10.2307/j.ctvcm4gk0. General conceptual reference only; exact model derivation not established."
}

{
  "id": "measles-vaccination-coverage-model-epi",
  "name": "Measles Vaccination Coverage Model",
  "description": "Illustrative Measles Vaccination Coverage Model.\n\nSource reconciliation 2026-10-20: Corrected the unrelated chondrogenesis DOI to the publisher book record. This correction establishes bibliographic identity only. This generated definition is illustrative; no specific book chapter/equation, parameter table, initial values, unit system or calibration has been traced to it. The vaccination flow is fixed at zero although vaccination_rate is 0.01. The exposure law references beta and N without corresponding variables; vaccine efficacy 0.97 and initial coverage have no traced empirical evidence. Equations, initial values, flow topology and layout are unchanged. Scientific/source fidelity remains unverified.",
